    // MARK: - Volume callbacks

    private func wireVolumeCallbacks() {
        let appState = appState
        let speech = speechManager
        let qa = quickAction
        let store = quickActionStore

        volumeHandler.onSingleDown = {
            print("[VolumeHandler] singleDown")
            Task { @MainActor in
                if qa.isOpen {
                    qa.cycle()
                } else {
                    withAnimation(.spring(response: 0.35, dampingFraction: 0.8)) {
                        appState.cycleSurface()
                    }
                }
            }
        }
        volumeHandler.onDoubleDown = {
            print("[VolumeHandler] doubleDown")
            Task { @MainActor in
                if qa.isOpen {
                    qa.dismiss()
                } else {
                    withAnimation(.spring(response: 0.3, dampingFraction: 0.85)) {
                        appState.cycleWorkspace()
                    }
                }
            }
        }
        volumeHandler.onSingleUp = {
            print("[VolumeHandler] singleUp")
            Task { @MainActor in
                if qa.isOpen {
                    // Confirm selected action
                    qa.execute()
                    DispatchQueue.main.asyncAfter(deadline: .now() + 0.5) {
                        appState.refreshSurfaces()
                    }
                } else if speech.isRecording {
                    // Stop recording and send
                    let pending = speech.transcript
                    try? await Task.sleep(nanoseconds: 300_000_000)
                    let text = speech.stop()
                    let finalText = text.isEmpty ? pending : text
                    print("[Speech] sending: \(finalText)")
                    if !finalText.isEmpty, let surfaceID = appState.focusedSurfaceID {
                        let autoSubmit = UserDefaults.standard.bool(forKey: "autoSubmitSpeech")
                        let toSend = autoSubmit ? finalText + "\n" : finalText
                        appState.sendText(toSend, to: surfaceID)
                    }
                } else {
                    // Start recording
                    speech.start()
                }
            }
        }
        volumeHandler.onDoubleUp = {
            print("[VolumeHandler] doubleUp → quickActions")
            Task { @MainActor in
                if qa.isOpen {
                    qa.dismiss()
                } else if let surface = appState.surfaces.first(where: { $0.id == appState.focusedSurfaceID })
                            ?? appState.surfaces.first {
                    let sid = surface.id
                    qa.open(with: QuickActionBuilder.build(surfaceID: sid, appState: appState, store: store))
                }
            }
        }
    }
}

import Speech
import AVFoundation

@MainActor
final class SpeechInputManager: ObservableObject {
    @Published var transcript = ""
    @Published var isRecording = false

    private let speechRecognizer = SFSpeechRecognizer(locale: .current)
    private var recognitionRequest: SFSpeechAudioBufferRecognitionRequest?
    private var recognitionTask: SFSpeechRecognitionTask?
    private let audioEngine = AVAudioEngine()

    func requestPermissions() {
        SFSpeechRecognizer.requestAuthorization { status in
            print("[Speech] authorization: \(status.rawValue)")
        }
        AVAudioSession.sharedInstance().requestRecordPermission { granted in
            print("[Speech] microphone permission: \(granted)")
        }
    }

    func start() {
        guard !isRecording else { return }
        transcript = ""

        guard let speechRecognizer, speechRecognizer.isAvailable else {
            print("[Speech] recognizer unavailable")
            return
        }

        do {
            let session = AVAudioSession.sharedInstance()
            try session.setCategory(.playAndRecord, mode: .measurement, options: [.duckOthers, .defaultToSpeaker])
            try session.setActive(true, options: .notifyOthersOnDeactivation)

            recognitionRequest = SFSpeechAudioBufferRecognitionRequest()
            guard let request = recognitionRequest else { return }
            request.shouldReportPartialResults = true

            recognitionTask = speechRecognizer.recognitionTask(with: request) { [weak self] result, error in
                if let error {
                    print("[Speech] recognition error: \(error.localizedDescription)")
                }
                if let result {
                    Task { @MainActor [weak self] in
                        self?.transcript = result.bestTranscription.formattedString
                        print("[Speech] transcript: \(result.bestTranscription.formattedString)")
                    }
                }
            }

            let inputNode = audioEngine.inputNode
            let fmt = inputNode.outputFormat(forBus: 0)

            // Guard against zero-sample-rate format which causes silent failure
            guard fmt.sampleRate > 0 else {
                print("[Speech] inputNode format has zero sample rate: \(fmt)")
                cleanupAudio()
                return
            }

            inputNode.installTap(onBus: 0, bufferSize: 1024, format: fmt) { [weak self] buffer, _ in
                self?.recognitionRequest?.append(buffer)
            }

            audioEngine.prepare()
            try audioEngine.start()
            isRecording = true
            print("[Speech] started recording")
        } catch {
            print("[Speech] start failed: \(error.localizedDescription)")
            cleanupAudio()
        }
    }

    func stop() -> String {
        print("[Speech] stopping, transcript: \(transcript)")
        let result = transcript
        cleanupAudio()
        return result
    }

    private func cleanupAudio() {
        audioEngine.stop()
        audioEngine.inputNode.removeTap(onBus: 0)
        recognitionRequest?.endAudio()
        recognitionTask?.finish()
        recognitionTask = nil
        recognitionRequest = nil
        isRecording = false
        transcript = ""

        // Restore session for volume KVO
        try? AVAudioSession.sharedInstance().setCategory(.ambient)
        try? AVAudioSession.sharedInstance().setActive(true)
    }
}

import SwiftUI

struct QuickActionSettingsView: View {
    @EnvironmentObject var store: QuickActionStore
    @State private var editingAction: CustomQuickAction?
    @State private var isAddingNew = false

    // Built-in action definitions for the toggle list
    private static let builtInActions: [(label: String, icon: String, section: String)] = [
        ("Enter", "return", "Input"),
        ("Ctrl+C", "xmark.circle", "Input"),
        ("Ctrl+D", "eject", "Input"),
        ("Ctrl+Z", "pause.circle", "Input"),
        ("Clear", "trash", "Input"),
        ("Tab", "arrow.right.to.line", "Input"),
        ("Escape", "escape", "Input"),
        ("Up Arrow", "arrow.up", "Input"),
        ("Down Arrow", "arrow.down", "Input"),
        ("Split Right", "rectangle.split.2x1", "Terminal"),
        ("Split Down", "rectangle.split.1x2", "Terminal"),
        ("New Terminal", "plus.rectangle", "Terminal"),
        ("Close Surface", "xmark.rectangle", "Terminal"),
        ("New Workspace", "square.grid.2x2", "Workspace"),
    ]

    private var builtInSections: [(String, [(label: String, icon: String, section: String)])] {
        let grouped = Dictionary(grouping: Self.builtInActions, by: \.section)
        return ["Input", "Terminal", "Workspace"].compactMap { section in
            guard let items = grouped[section] else { return nil }
            return (section, items)
